(227536, 13224, 3981, '<td valign="top">I love this shot!  Your lighting is perfect!</td>', 'I love this shot!  Your lighting is perfect!', '2003-03-03 11:36:15.000000', NULL, 1),
(227537, 13426, 5082, '<td valign="top">Very creative shot... I still say the shell has a yellow cast, though. ;-)</td>', 'Very creative shot... I still say the shell has a yellow cast, though. ;-)', '2003-03-03 11:36:40.000000', NULL, 1),
(227538, 13283, 6870, '<td valign="top">Colors and contrasts are well done, and I like the concept. Egg is in focus; have you tried making the machinery in focus, too?</td>', 'Colors and contrasts are well done, and I like the concept. Egg is in focus; have you tried making the machinery in focus, too?', '2003-03-03 11:39:57.000000', NULL, 1),
(227540, 13266, 3981, '<td valign="top">Clever shot and well done, too.  Composition couldn''t be better!</td>', 'Clever shot and well done, too.  Composition couldn''t be better!', '2003-03-03 11:40:59.000000', NULL, 1),
(227541, 13390, 6870, '<td valign="top">White on white works well here; nice use of shadows. The egg is not quite in focus, especially on those crucial edges.</td>', 'White on white works well here; nice use of shadows. The egg is not quite in focus, especially on those crucial edges.', '2003-03-03 11:41:11.000000', NULL, 1),
(227543, 13488, 6870, '<td valign="top">Nice still life. Shadows and natural lighting work well. The reflection of light on the sign is a bit annoying; have you tried diffusing the light?</td>', 'Nice still life. Shadows and natural lighting work well. The reflection of light on the sign is a bit annoying; have you tried diffusing the light?', '2003-03-03 11:42:25.000000', NULL, 1),
(227544, 13496, 368, '<td valign="top">hehehehe ... this is great - too funny :)</td>', 'hehehehe ... this is great - too funny :)', '2003-03-03 11:43:37.000000', NULL, 1),
(227545, 13458, 6870, '<td valign="top">Interesting shot ("interesting" in a good way). I like the idea. I really enjoy how the black edges are invisible. You might try more definition of the egg through careful lighting/shading.</td>', 'Interesting shot ("interesting" in a good way). I like the idea. I really enjoy how the black edges are invisible. You might try more definition of the egg through careful lighting/shading.', '2003-03-03 11:44:02.000000', NULL, 1),
