INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(228694, 13258, 6182, '<td valign="top">interesting idea and good photo overall...a bit more clarity would make it better and I''d probably crop closer (just my opinion).</td>', 'interesting idea and good photo overall...a bit more clarity would make it better and I''d probably crop closer (just my opinion).', '2003-03-04 09:12:40.000000', NULL, 1),
(228696, 13394, 6182, '<td valign="top">I like the lighting effect you created here...nice angular composition also.  Better focus would make this a winner.</td>', 'I like the lighting effect you created here...nice angular composition also.  Better focus would make this a winner.', '2003-03-04 09:14:19.000000', NULL, 1),
(228697, 13449, 6182, '<td valign="top">Interesting idea...i would have put the peeps in an egg carton also!!   Nice use of color...I just personally don''t like the yellow egg carton...would have tried to desaturate yellows maybe.  Original!</td>', 'Interesting idea...i would have put the peeps in an egg carton also!!   Nice use of color...I just personally don''t like the yellow egg carton...would have tried to desaturate yellows maybe.  Original!', '2003-03-04 09:16:38.000000', NULL, 1),
(228699, 13276, 6182, '<td valign="top">Fun idea!...I''m a Colorado native.   My parents, especially my mother, are huge Bronco fans...10 year ticket holders!   I don''t really like football but this is a fun, original idea.</td>', 'Fun idea!...I''m a Colorado native.   My parents, especially my mother, are huge Bronco fans...10 year ticket holders!   I don''t really like football but this is a fun, original idea.', '2003-03-04 09:20:48.000000', NULL, 1),
(228700, 13270, 3724, '<td valign="top">the choice of the little (glass or plastic) rooster seems a little incongruous in terms of the other textures......   but as the meaning of your title dictates - the rooster is required.  The egg is gorgeous and works well with the terricloth (or flannel?).</td>', 'the choice of the little (glass or plastic) rooster seems a little incongruous in terms of the other textures......   but as the meaning of your title dictates - the rooster is required.  The egg is gorgeous and works well with the terricloth (or flannel?).', '2003-03-04 09:23:33.000000', NULL, 1),
(228702, 13363, 6182, '<td valign="top">This is an absolutely beautiful still life!!   I would definitely hang this on my wall...would like it REALLY BIG!!! Are you taking orders on it?  10!!!</td>', 'This is an absolutely beautiful still life!!   I would definitely hang this on my wall...would like it REALLY BIG!!! Are you taking orders on it?  10!!!', '2003-03-04 09:25:31.000000', NULL, 1),
