(229058, 13266, 6150, '<td valign="top">Great Shot.  I would be interested in knowing how you did that.</td>', 'Great Shot.  I would be interested in knowing how you did that.', '2003-03-04 16:47:56.000000', NULL, 1),
(229059, 13214, 6150, '<td valign="top">Great shot.  My favorite so far.  Keep up the good work.</td>', 'Great shot.  My favorite so far.  Keep up the good work.', '2003-03-04 16:51:30.000000', NULL, 1),
(229060, 13378, 6172, '<td valign="top">Interesting shot, don''t understand the title, am I supposed to?</td>', 'Interesting shot, don''t understand the title, am I supposed to?', '2003-03-04 16:55:10.000000', NULL, 1),
(229061, 13355, 6172, '<td valign="top">Why is the image size so small?  You are allowed up to 150kb, you should take advantage of it.</td>', 'Why is the image size so small?  You are allowed up to 150kb, you should take advantage of it.', '2003-03-04 16:56:15.000000', NULL, 1),
(229062, 13235, 6172, '<td valign="top">Looks like a snapshot.</td>', 'Looks like a snapshot.', '2003-03-04 16:56:34.000000', NULL, 1),
(229065, 13394, 6172, '<td valign="top">Looks like some cosmic event.</td>', 'Looks like some cosmic event.', '2003-03-04 16:59:02.000000', NULL, 1),
(229067, 13250, 6172, '<td valign="top">The one in the lower right is cropped off, doesn''t seem like a good effect to me.  The rest of the shot is nice, an interesting (if somewhat weird) concept.  I like it.  Nice focus, lighting, colors.</td>', 'The one in the lower right is cropped off, doesn''t seem like a good effect to me.  The rest of the shot is nice, an interesting (if somewhat weird) concept.  I like it.  Nice focus, lighting, colors.', '2003-03-04 17:00:48.000000', NULL, 1),
(229068, 13510, 5753, '<td valign="top">These eggs really stand out, almost in 3D!!  Good job on the light.  Some things are always better when kept simple, like this compo.  8</td>', 'These eggs really stand out, almost in 3D!!  Good job on the light.  Some things are always better when kept simple, like this compo.  8', '2003-03-04 17:02:18.000000', NULL, 1),
(229069, 13334, 6172, '<td valign="top">The photo is so two dimensional, it''s too bad.  I also don''t like what you did to the corners.  Nice focus, a little glare in the middle of the egg, nice colors.</td>', 'The photo is so two dimensional, it''s too bad.  I also don''t like what you did to the corners.  Nice focus, a little glare in the middle of the egg, nice colors.', '2003-03-04 17:04:16.000000', NULL, 1),
(229071, 13292, 6172, '<td valign="top">Could you explain please?  It looks too much like you are being disrespectful to the flag and the union.  A good explanation could change the low score I gave you.</td>', 'Could you explain please?  It looks too much like you are being disrespectful to the flag and the union.  A good explanation could change the low score I gave you.', '2003-03-04 17:10:50.000000', NULL, 1),
(229072, 13257, 6110, '<td valign="top">Nice lighting!</td>', 'Nice lighting!', '2003-03-04 17:11:20.000000', NULL, 1),
(229073, 13382, 6172, '<td valign="top">I don''t understand the title.   The shot is interesting, but it kind of leaves me hanging about the meaning.  Those staples look like a lot of work!  If you can send me a message making some sense out of the title, I will raise the score.</td>', 'I don''t understand the title.   The shot is interesting, but it kind of leaves me hanging about the meaning.  Those staples look like a lot of work!  If you can send me a message making some sense out of the title, I will raise the score.', '2003-03-04 17:11:35.000000', NULL, 1),
(229076, 13513, 6110, '<td valign="top">Hope your lens didn''t need too much cleaning after this one :-)  Clever idea, great timing.  Photo needs a level adjustment, too dark.</td>', 'Hope your lens didn''t need too much cleaning after this one :-)  Clever idea, great timing.  Photo needs a level adjustment, too dark.', '2003-03-04 17:14:15.000000', NULL, 1),
(229077, 13232, 6110, '<td valign="top">Just a touch overexposed, some detail lost on the egg.</td>', 'Just a touch overexposed, some detail lost on the egg.', '2003-03-04 17:15:43.000000', NULL, 1),
(229079, 13321, 6110, '<td valign="top">Nice macro.  Use a tripod and timer or cable release so your reflection isn''t in the shot.</td>', 'Nice macro.  Use a tripod and timer or cable release so your reflection isn''t in the shot.', '2003-03-04 17:18:57.000000', NULL, 1),
(229080, 13266, 6110, '<td valign="top">very cool idea</td>', 'very cool idea', '2003-03-04 17:20:51.000000', NULL, 1),
(229083, 13206, 6150, '<td valign="top">I can give you 10 good reasons why I love this shot.  Keep up the good work.</td>', 'I can give you 10 good reasons why I love this shot.  Keep up the good work.', '2003-03-04 17:22:29.000000', NULL, 1),
(229084, 13306, 6150, '<td valign="top">This is a really nice shot.  I''m very interested in how you did this one.  The little child is so full of personality. I''m giving you a 10 on this one.  I can''t see one thing wrong with it but I''m far from an expert.</td>', 'This is a really nice shot.  I''m very interested in how you did this one.  The little child is so full of personality. I''m giving you a 10 on this one.  I can''t see one thing wrong with it but I''m far from an expert.', '2003-03-04 17:22:58.000000', NULL, 1),
(229085, 13492, 6110, '<td valign="top">interesting abstract, not sure what I''m seeing, but it''s enjoyable.</td>', 'interesting abstract, not sure what I''m seeing, but it''s enjoyable.', '2003-03-04 17:23:39.000000', NULL, 1),
(229090, 13179, 1005, '<td valign="top">Really neat idea, but the projected image isn''t clear, so the overall impression isn''t that good.  6 Swash</td>', 'Really neat idea, but the projected image isn''t clear, so the overall impression isn''t that good.  6 Swash', '2003-03-04 17:33:15.000000', NULL, 1),
(229093, 13496, 2223, '<td valign="top">is that a NY license plate? too bad about the crash, hope everyone''s okay :-)</td>', 'is that a NY license plate? too bad about the crash, hope everyone''s okay :-)', '2003-03-04 17:41:54.000000', NULL, 1),
(229094, 13135, 2223, '<td valign="top">creepy..reminds me of alien.</td>', 'creepy..reminds me of alien.', '2003-03-04 17:43:14.000000', NULL, 1),
(229095, 13474, 2223, '<td valign="top">lol!</td>', 'lol!', '2003-03-04 17:44:25.000000', NULL, 1),
