(229097, 13234, 2223, '<td valign="top">this is very good. the lighting and focus are perfect. the border works well.</td>', 'this is very good. the lighting and focus are perfect. the border works well.', '2003-03-04 17:47:27.000000', NULL, 1),
(229109, 13430, 1005, '<td valign="top">Bath salts in the round....really fun idea, but the focus is on the back of the carton, oops.  Are they different scents or just differently colored (american)?  6 Swash</td>', 'Bath salts in the round....really fun idea, but the focus is on the back of the carton, oops.  Are they different scents or just differently colored (american)?  6 Swash', '2003-03-04 18:06:17.000000', NULL, 1),
(229112, 13379, 5728, '<td valign="top">This is good! Very simple but a lot of impact! You composed this image perfectly and the border and title is very fitting.</td>', 'This is good! Very simple but a lot of impact! You composed this image perfectly and the border and title is very fitting.', '2003-03-04 18:11:00.000000', NULL, 1),
(229114, 13417, 5728, '<td valign="top">Simple but subtle good! You got a form of lips in the egg holder. Nice!</td>', 'Simple but subtle good! You got a form of lips in the egg holder. Nice!', '2003-03-04 18:12:14.000000', NULL, 1),
(229117, 13353, 1005, '<td valign="top">Risky shot (soft focus, right?)  I''ll bet you''re getting a lot of "focus" comments!  It''s well done, but I''m not certain about the background......7 Swash</td>', 'Risky shot (soft focus, right?)  I''ll bet you''re getting a lot of "focus" comments!  It''s well done, but I''m not certain about the background......7 Swash', '2003-03-04 18:15:04.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(229118, 13340, 5728, '<td valign="top">This is original, good capture! The grass looks a little too long for a golf course or were you caught in the rough? lol. I think it might be sharpened a little too much. Look at the "M" on the egg and you can see a little sharpness halo around it.</td>', 'This is original, good capture! The grass looks a little too long for a golf course or were you caught in the rough? lol. I think it might be sharpened a little too much. Look at the "M" on the egg and you can see a little sharpness halo around it.', '2003-03-04 18:18:20.000000', NULL, 1),
(229123, 13495, 5728, '<td valign="top">Great idea! This really looks like a clock! Nice composition, I like the way you have the main clock times in white and the rest in brown. Good luck with this!</td>', 'Great idea! This really looks like a clock! Nice composition, I like the way you have the main clock times in white and the rest in brown. Good luck with this!', '2003-03-04 18:24:49.000000', NULL, 1),
(229124, 13268, 2158, '<td valign="top">I can''t help feeling this would have looked better with a black background.</td>', 'I can''t help feeling this would have looked better with a black background.', '2003-03-04 18:26:04.000000', NULL, 1),
(229130, 13345, 6202, '<td valign="top">nice use of color.</td>', 'nice use of color.', '2003-03-04 18:35:43.000000', NULL, 1),
(229131, 13275, 6202, '<td valign="top">Cute kitten, likes the egg too I see.</td>', 'Cute kitten, likes the egg too I see.', '2003-03-04 18:36:20.000000', NULL, 1),
(229132, 13325, 6202, '<td valign="top">Definately bright and attention getting</td>', 'Definately bright and attention getting', '2003-03-04 18:36:51.000000', NULL, 1),
(229134, 13376, 6110, '<td valign="top">Nice use of light &amp; shadows</td>', 'Nice use of light & shadows', '2003-03-04 18:40:06.000000', NULL, 1),
(229135, 13220, 616, '<td valign="top">Awesome! This is an incredible photo. The idea here is brilliant, i like the fact that it is offset. Lighting and tones are great.</td>', 'Awesome! This is an incredible photo. The idea here is brilliant, i like the fact that it is offset. Lighting and tones are great.', '2003-03-04 18:41:57.000000', NULL, 1),
(229136, 13378, 6110, '<td valign="top">Funny idea, background color clashes IMO</td>', 'Funny idea, background color clashes IMO', '2003-03-04 18:42:55.000000', NULL, 1),
(229137, 13261, 6110, '<td valign="top">Nice lighting, good use of reflections.</td>', 'Nice lighting, good use of reflections.', '2003-03-04 18:43:49.000000', NULL, 1),
(229140, 13411, 6110, '<td valign="top">Good stop motion.</td>', 'Good stop motion.', '2003-03-04 18:45:46.000000', NULL, 1),
(229142, 13438, 6110, '<td valign="top">Why focus on the basket when the theme is eggs?</td>', 'Why focus on the basket when the theme is eggs?', '2003-03-04 18:47:09.000000', NULL, 1),
(229143, 13215, 6110, '<td valign="top">Nice composition, good demonstration of minimalism.  I like it!</td>', 'Nice composition, good demonstration of minimalism.  I like it!', '2003-03-04 18:49:56.000000', NULL, 1),
(229144, 13372, 1005, '<td valign="top">Very strange, it must be a weaver!  (and it weaves golden baskets, would this be some relative of the goose and it''s golden eggs? Hint - you might want to loose the manufactured basket).  7 Swash</td>', 'Very strange, it must be a weaver!  (and it weaves golden baskets, would this be some relative of the goose and it''s golden eggs? Hint - you might want to loose the manufactured basket).  7 Swash', '2003-03-04 18:50:02.000000', NULL, 1),
(229149, 13497, 616, '<td valign="top">Nicely done! The lighting here is great, I like how it has created different tones on the surface of the egg. The centering/cropping/positioning of the egg is very pleasing to the eye. What is also attrractive to my eye is that isn''t bland like the average egg.</td>', 'Nicely done! The lighting here is great, I like how it has created different tones on the surface of the egg. The centering/cropping/positioning of the egg is very pleasing to the eye. What is also attrractive to my eye is that isn''t bland like the average egg.', '2003-03-04 18:58:57.000000', NULL, 1),
(229150, 13457, 772, '<td valign="top">this is an excellent shot.. the subtle red lions on the eggs stand out just perfectly.. the shallow depth of field also works well.. - setzler</td>', 'this is an excellent shot.. the subtle red lions on the eggs stand out just perfectly.. the shallow depth of field also works well.. - setzler', '2003-03-04 18:59:25.000000', NULL, 1),
(229151, 13320, 772, '<td valign="top">interesting composition :)  the lighting may be a bit too powerful for my personal taste, but the theme is nice :) - setzler</td>', 'interesting composition :)  the lighting may be a bit too powerful for my personal taste, but the theme is nice :) - setzler', '2003-03-04 19:01:17.000000', NULL, 1),
(229152, 13209, 772, '<td valign="top">excellent shot... the lighting is strong and the ''earth'' in the background is a great touch... = 10 - setzler</td>', 'excellent shot... the lighting is strong and the ''earth'' in the background is a great touch... = 10 - setzler', '2003-03-04 19:05:17.000000', NULL, 1),
(229153, 13461, 6600, '<td valign="top">I like the colors and the premise.  If you could have stood the the real egg on end to make it ''stand'' out even more it would have been better (in my opinion).  Then I might have named it "Standing Out In A Crowd"</td>', 'I like the colors and the premise.  If you could have stood the the real egg on end to make it ''stand'' out even more it would have been better (in my opinion).  Then I might have named it "Standing Out In A Crowd"', '2003-03-04 19:07:01.000000', NULL, 1),
(229154, 13452, 6600, '<td valign="top">Picked the right plant for the job!  Nicely done.  Like the idea!</td>', 'Picked the right plant for the job!  Nicely done.  Like the idea!', '2003-03-04 19:08:01.000000', NULL, 1),
(229156, 13234, 6600, '<td valign="top">Nice touch having it layed out on a mirror....</td>', 'Nice touch having it layed out on a mirror....', '2003-03-04 19:10:10.000000', NULL, 1),
(229159, 13263, 6110, '<td valign="top">Nice colorful shot, good composition.</td>', 'Nice colorful shot, good composition.', '2003-03-04 19:14:36.000000', NULL, 1),
(229160, 13390, 6110, '<td valign="top">Good minimalistic composition</td>', 'Good minimalistic composition', '2003-03-04 19:15:50.000000', NULL, 1),
(229161, 13364, 6600, '<td valign="top">What can I say....  I almost have to like yours since it''s very similar to my entry (Eggtc., Eggtc.).  I am of the opinion that if you could have hid your method of attaching the eggs it would be an improvement (as it is, it''s a tad distracting).  I really like the reflection on the surface and dark contrast at the top of the photo.</td>', 'What can I say....  I almost have to like yours since it''s very similar to my entry (Eggtc., Eggtc.).  I am of the opinion that if you could have hid your method of attaching the eggs it would be an improvement (as it is, it''s a tad distracting).  I really like the reflection on the surface and dark contrast at the top of the photo.', '2003-03-04 19:16:29.000000', NULL, 1),
(229163, 13493, 616, '<td valign="top">Nicely done! The use of the lens flare was a nice touch, it really adds some substance to the shot. The eggs work out very well here in this composition, yet it leaves me wondering why you chose to set the eggs up in this paticular arrangement.</td>', 'Nicely done! The use of the lens flare was a nice touch, it really adds some substance to the shot. The eggs work out very well here in this composition, yet it leaves me wondering why you chose to set the eggs up in this paticular arrangement.', '2003-03-04 19:18:31.000000', NULL, 1),
(229168, 13181, 6600, '<td valign="top">Like the pronounced ''texture'' that this pic displays.  The composition is very good in my (non-professional) opinion.  Nice shot!</td>', 'Like the pronounced ''texture'' that this pic displays.  The composition is very good in my (non-professional) opinion.  Nice shot!', '2003-03-04 19:21:37.000000', NULL, 1),
(229172, 13308, 6600, '<td valign="top">I like the ''newness'' idea of this shot.....  I''m a bit envious!  I wish I had the signs of spring in my world (Minnesota).</td>', 'I like the ''newness'' idea of this shot.....  I''m a bit envious!  I wish I had the signs of spring in my world (Minnesota).', '2003-03-04 19:27:15.000000', NULL, 1),
(229177, 13446, 4049, '<td valign="top">You''ve got a nice body!</td>', 'You''ve got a nice body!', '2003-03-04 19:31:13.000000', NULL, 1),
(229182, 13303, 3280, '<td valign="top">Good color and focus, the window glare in the balls is a bit distracting</td>', 'Good color and focus, the window glare in the balls is a bit distracting', '2003-03-04 19:36:09.000000', NULL, 1),
(229183, 13382, 3280, '<td valign="top">Very cool!  It seems to be just a bit over sharpened.  I love the idea though.</td>', 'Very cool!  It seems to be just a bit over sharpened.  I love the idea though.', '2003-03-04 19:37:15.000000', NULL, 1),
(229184, 13271, 3280, '<td valign="top">Good lighting and color.  May have worked better in another bowl that was less like the color of the eggs though.</td>', 'Good lighting and color.  May have worked better in another bowl that was less like the color of the eggs though.', '2003-03-04 19:37:56.000000', NULL, 1),
(229186, 13187, 3280, '<td valign="top">Very creative, and I like the tone and color.  Good focus as well. May have worked just a bit better if the top of the reflection wasn''t cut off.</td>', 'Very creative, and I like the tone and color.  Good focus as well. May have worked just a bit better if the top of the reflection wasn''t cut off.', '2003-03-04 19:38:55.000000', NULL, 1),
(229188, 13278, 3280, '<td valign="top">Nice,  colors seem just a bit washed out though.  Perhaps by lightening the contrast too much?  Good job.</td>', 'Nice,  colors seem just a bit washed out though.  Perhaps by lightening the contrast too much?  Good job.', '2003-03-04 19:40:13.000000', NULL, 1),
(229189, 13499, 3280, '<td valign="top">Good idea, but the lack of focus and too much grain did Humpty in!</td>', 'Good idea, but the lack of focus and too much grain did Humpty in!', '2003-03-04 19:40:51.000000', NULL, 1),
(229190, 13208, 6600, '<td valign="top">I think this is a very clever idea.  Nice penmanship too!  Nicely done.</td>', 'I think this is a very clever idea.  Nice penmanship too!  Nicely done.', '2003-03-04 19:41:15.000000', NULL, 1),
(229191, 13376, 3280, '<td valign="top">Great use of textures and color.  The more I look at it, the better I like it.  Seems like the contrast could have been set a bit darker.</td>', 'Great use of textures and color.  The more I look at it, the better I like it.  Seems like the contrast could have been set a bit darker.', '2003-03-04 19:42:02.000000', NULL, 1),
(229193, 13445, 3280, '<td valign="top">Very creative, but you need to work on your lighting.  Looks like an on camera flash with way too much glare.  A side light or two her would have really cut the glare and brought out the colors.</td>', 'Very creative, but you need to work on your lighting.  Looks like an on camera flash with way too much glare.  A side light or two her would have really cut the glare and brought out the colors.', '2003-03-04 19:43:19.000000', NULL, 1),
(229194, 13190, 3280, '<td valign="top">Nice and sharp and looks like a mess.  How many scrambled eggs did you eat that day?!?</td>', 'Nice and sharp and looks like a mess.  How many scrambled eggs did you eat that day?!?', '2003-03-04 19:43:56.000000', NULL, 1),
