(229525, 13249, 3724, '<td valign="top">nice macro.......</td>', 'nice macro.......', '2003-03-05 07:49:42.000000', NULL, 1),
(229526, 13203, 3724, '<td valign="top">....like the heavy frame for this and buff colour which you have used......   nicely composed picture - the negative space around the arm and hand is proportional.  The flying eggs thrown at the viewer, though a little static, are flying nonetheless.  Cool shot.</td>', '....like the heavy frame for this and buff colour which you have used......   nicely composed picture - the negative space around the arm and hand is proportional.  The flying eggs thrown at the viewer, though a little static, are flying nonetheless.  Cool shot.', '2003-03-05 08:01:20.000000', NULL, 1),
(229528, 13372, 772, '<td valign="top">I like the colorful eggs... I think a tighter crop that left out the background would be good also.. nice work :) - setzler</td>', 'I like the colorful eggs... I think a tighter crop that left out the background would be good also.. nice work :) - setzler', '2003-03-05 08:04:21.000000', NULL, 1),
(229529, 13365, 772, '<td valign="top">interesting concept... I think a darker background like blue or purple would contrast with the egg nicely :) - setzler</td>', 'interesting concept... I think a darker background like blue or purple would contrast with the egg nicely :) - setzler', '2003-03-05 08:05:04.000000', NULL, 1),
(229530, 13435, 772, '<td valign="top">This image is a bit too small and it appears to be out of focus also... - setzler</td>', 'This image is a bit too small and it appears to be out of focus also... - setzler', '2003-03-05 08:05:28.000000', NULL, 1),
(229531, 13283, 772, '<td valign="top">excellent concept.. the depth of field works very well here also.. nice work :) - setzler</td>', 'excellent concept.. the depth of field works very well here also.. nice work :) - setzler', '2003-03-05 08:05:55.000000', NULL, 1),
(229532, 13199, 772, '<td valign="top">nice detail on the egg... the surface color and texture  look good... simplicity works well in this shot :) - setzler</td>', 'nice detail on the egg... the surface color and texture  look good... simplicity works well in this shot :) - setzler', '2003-03-05 08:06:27.000000', NULL, 1),
(229534, 13309, 772, '<td valign="top">I don''t normally comment on borders, but I think this border is a bit distracting from your subject.  I think the image woudl be much stronger without this particular border.. - setzler</td>', 'I don''t normally comment on borders, but I think this border is a bit distracting from your subject.  I think the image woudl be much stronger without this particular border.. - setzler', '2003-03-05 08:07:09.000000', NULL, 1),
(229535, 13356, 772, '<td valign="top">cute idea :) - setzler</td>', 'cute idea :) - setzler', '2003-03-05 08:07:43.000000', NULL, 1),
(229541, 13491, 4267, '<td valign="top">oh man, hehe, this had me giggling from the get go... that hair just makes it look more disgusting! hehehe.. and while perhaps negative impact, it is still nonthelesss visual impact! and that''s actully good! really great colors too! as for the egg thing, well I am not too up on meringue.. is this some sort of egg conconcoction? my guess is most won''t recognize this as an egg, and that could hurt the score badly.</td>', 'oh man, hehe, this had me giggling from the get go... that hair just makes it look more disgusting! hehehe.. and while perhaps negative impact, it is still nonthelesss visual impact! and that''s actully good! really great colors too! as for the egg thing, well I am not too up on meringue.. is this some sort of egg conconcoction? my guess is most won''t recognize this as an egg, and that could hurt the score badly.', '2003-03-05 08:32:42.000000', NULL, 1),
(229543, 13307, 772, '<td valign="top">interesting black and white... i think this shot would be stronger if the egg silhouette was in sharp focus... - setzler</td>', 'interesting black and white... i think this shot would be stronger if the egg silhouette was in sharp focus... - setzler', '2003-03-05 08:35:07.000000', NULL, 1),
(229544, 13399, 772, '<td valign="top">nice use of perspective here... i think this shot would also be strong with a shallow depth of field... nice work :) - setzler</td>', 'nice use of perspective here... i think this shot would also be strong with a shallow depth of field... nice work :) - setzler', '2003-03-05 08:35:41.000000', NULL, 1),
