(230391, 13495, 772, '<td valign="top">nice use of lighting and contrast... excellent shot :) - setzler</td>', 'nice use of lighting and contrast... excellent shot :) - setzler', '2003-03-06 10:45:04.000000', NULL, 1),
(230393, 13413, 772, '<td valign="top">This is a neat idea but the visual appeal, to me, is a bit weak overall.. - setzler</td>', 'This is a neat idea but the visual appeal, to me, is a bit weak overall.. - setzler', '2003-03-06 10:45:45.000000', NULL, 1),
