(230405, 13214, 6855, '<td valign="top">This is really pretty!  I like it alot.</td>', 'This is really pretty!  I like it alot.', '2003-03-06 11:19:44.000000', NULL, 1),
(230409, 13417, 6855, '<td valign="top">The reflection and angle here are fascinating - I''ve been staring at it forever. Great shot.</td>', 'The reflection and angle here are fascinating - I''ve been staring at it forever. Great shot.', '2003-03-06 11:20:52.000000', NULL, 1),
(230410, 13480, 6855, '<td valign="top">I LOVE this!  Very clever, and the colors are gorgeous.</td>', 'I LOVE this!  Very clever, and the colors are gorgeous.', '2003-03-06 11:21:34.000000', NULL, 1),
(230411, 13225, 6855, '<td valign="top">Lighting and shadows here are gorgeous! Very clever!</td>', 'Lighting and shadows here are gorgeous! Very clever!', '2003-03-06 11:22:20.000000', NULL, 1),
