(230424, 13363, 6855, '<td valign="top">Gorgeous!  I love the use of colors and the overall feel of this. Very well done!</td>', 'Gorgeous!  I love the use of colors and the overall feel of this. Very well done!', '2003-03-06 11:30:25.000000', NULL, 1),
(230425, 13274, 6855, '<td valign="top">Clever title and a great photo! Well done.</td>', 'Clever title and a great photo! Well done.', '2003-03-06 11:31:32.000000', NULL, 1),
(230426, 13488, 6855, '<td valign="top">Very clever and cute.</td>', 'Very clever and cute.', '2003-03-06 11:32:09.000000', NULL, 1),
(230427, 13508, 6855, '<td valign="top">Where''s the ham??? Great shot.</td>', 'Where''s the ham??? Great shot.', '2003-03-06 11:33:37.000000', NULL, 1),
