(230429, 13194, 4536, '<td valign="top">Well shot, nice lighting. I do find it a bit too hot in areas and I am not sure what the relationship is between the egg and the rose are.</td>', 'Well shot, nice lighting. I do find it a bit too hot in areas and I am not sure what the relationship is between the egg and the rose are.', '2003-03-06 11:35:00.000000', NULL, 1),
(230430, 13172, 6855, '<td valign="top">Very clever!</td>', 'Very clever!', '2003-03-06 11:36:19.000000', NULL, 1),
