(230432, 13272, 4536, '<td valign="top">It is a bit out of focus and wrinkled sheets as a background drive me nuts! :). Nice subject and framing.</td>', 'It is a bit out of focus and wrinkled sheets as a background drive me nuts! :). Nice subject and framing.', '2003-03-06 11:40:32.000000', NULL, 1),
(230433, 13480, 4536, '<td valign="top">Creative lighting. The composition is a bit static, IMO.</td>', 'Creative lighting. The composition is a bit static, IMO.', '2003-03-06 11:42:07.000000', NULL, 1),
(230435, 13450, 6230, '<td valign="top">More effort in control of lighting required, especially in still life photography. Harsh lighting/flash threw shadows onto the wall behind the toy.</td>', 'More effort in control of lighting required, especially in still life photography. Harsh lighting/flash threw shadows onto the wall behind the toy.', '2003-03-06 11:44:58.000000', NULL, 1),
(230436, 13269, 772, '<td valign="top">interesting use of color... - setzler</td>', 'interesting use of color... - setzler', '2003-03-06 11:46:52.000000', NULL, 1),
