(231340, 13274, 5865, '<td valign="top">Ingenious idea.  I liked the photograph but can''t quite figure out how you did it.</td>', 'Ingenious idea.  I liked the photograph but can''t quite figure out how you did it.', '2003-03-07 16:49:55.000000', NULL, 1),
(231341, 13391, 5865, '<td valign="top">A very good likeness :)</td>', 'A very good likeness :)', '2003-03-07 16:50:27.000000', NULL, 1),
(231342, 13314, 5865, '<td valign="top">Very novel idea.  I liked the added colour of the red tongue.  The lighting was good too.</td>', 'Very novel idea.  I liked the added colour of the red tongue.  The lighting was good too.', '2003-03-07 16:51:19.000000', NULL, 1),
(231343, 13292, 5865, '<td valign="top">Seemed like a brilliant way to get a message across.  Well done for thinking the shot up.</td>', 'Seemed like a brilliant way to get a message across.  Well done for thinking the shot up.', '2003-03-07 16:52:53.000000', NULL, 1),
(231344, 13363, 5865, '<td valign="top">The colours in this still life are superb.  I also like the lighting.  More light would have spoilt the shot for me.  A real work of art.</td>', 'The colours in this still life are superb.  I also like the lighting.  More light would have spoilt the shot for me.  A real work of art.', '2003-03-07 16:55:20.000000', NULL, 1),
(231345, 13317, 5865, '<td valign="top">I loved the lighting and the angle of the shot.  I wonder how you got the shape of the yoke?</td>', 'I loved the lighting and the angle of the shot.  I wonder how you got the shape of the yoke?', '2003-03-07 16:56:10.000000', NULL, 1),
(231346, 13234, 5865, '<td valign="top">I really enjoyed this composition.</td>', 'I really enjoyed this composition.', '2003-03-07 16:57:45.000000', NULL, 1),
(231348, 13494, 5865, '<td valign="top">A nice idea that has made a well composed shot.  The lighting makes the shot.  I really enjoyed the photograph.</td>', 'A nice idea that has made a well composed shot.  The lighting makes the shot.  I really enjoyed the photograph.', '2003-03-07 16:59:39.000000', NULL, 1),
(231349, 13409, 5865, '<td valign="top">A lovely composition.  Lots of negative space.  The bowl is in a good position.  I like it.</td>', 'A lovely composition.  Lots of negative space.  The bowl is in a good position.  I like it.', '2003-03-07 17:00:54.000000', NULL, 1),
(231350, 13172, 5865, '<td valign="top">A very novel idea.  Well done for thinking it up.</td>', 'A very novel idea.  Well done for thinking it up.', '2003-03-07 17:02:57.000000', NULL, 1),
(231352, 13307, 5865, '<td valign="top">I thought this was a super shot.  The symmetry of the flames (or whatever they  are) make the photograph for me.</td>', 'I thought this was a super shot.  The symmetry of the flames (or whatever they  are) make the photograph for me.', '2003-03-07 17:05:21.000000', NULL, 1),
(231353, 13373, 5865, '<td valign="top">Lovely photograph.  Compositionally it looks great.  Well done.</td>', 'Lovely photograph.  Compositionally it looks great.  Well done.', '2003-03-07 17:06:20.000000', NULL, 1),
(231355, 13282, 5865, '<td valign="top">Nice shot.  I am not sure if the choice of background colour is the best, but that is just my opinion.</td>', 'Nice shot.  I am not sure if the choice of background colour is the best, but that is just my opinion.', '2003-03-07 17:07:57.000000', NULL, 1),
(231357, 13255, 5865, '<td valign="top">Excellent idea for a photograph.  I think it was right to use black and white.</td>', 'Excellent idea for a photograph.  I think it was right to use black and white.', '2003-03-07 17:08:45.000000', NULL, 1),
(231358, 13485, 5865, '<td valign="top">The colours are beautiful and I like the lighting too.  Great shot.</td>', 'The colours are beautiful and I like the lighting too.  Great shot.', '2003-03-07 17:10:13.000000', NULL, 1),
(231360, 13187, 5865, '<td valign="top">I think you deserve a high score just for thinking that one up.  Well done.  I think everything is set up good too.  Good background, good lighting makes for a nice image.</td>', 'I think you deserve a high score just for thinking that one up.  Well done.  I think everything is set up good too.  Good background, good lighting makes for a nice image.', '2003-03-07 17:12:32.000000', NULL, 1),
(231361, 13214, 5865, '<td valign="top">The lighting on that background is fantastic.  Makes for a  nice image.</td>', 'The lighting on that background is fantastic.  Makes for a  nice image.', '2003-03-07 17:13:08.000000', NULL, 1),
(231363, 13460, 5865, '<td valign="top">I love the colour of this shot and the composition.  A really nice idea leading the eye out of the photograph like that.  Well done.</td>', 'I love the colour of this shot and the composition.  A really nice idea leading the eye out of the photograph like that.  Well done.', '2003-03-07 17:15:08.000000', NULL, 1),
(231367, 13306, 6110, '<td valign="top">Cute shot</td>', 'Cute shot', '2003-03-07 17:45:10.000000', NULL, 1),
(231368, 13244, 6110, '<td valign="top">Good setup.  Maybe just a tiny bit dark?</td>', 'Good setup.  Maybe just a tiny bit dark?', '2003-03-07 17:50:05.000000', NULL, 1),
(231369, 13474, 6110, '<td valign="top">good lighting</td>', 'good lighting', '2003-03-07 17:53:40.000000', NULL, 1),
(231370, 13172, 6110, '<td valign="top">Good setup</td>', 'Good setup', '2003-03-07 17:54:55.000000', NULL, 1),
(231373, 13473, 6110, '<td valign="top">Maybe try this from a lower angle (instead of straight down), to reduce the amount of background?</td>', 'Maybe try this from a lower angle (instead of straight down), to reduce the amount of background?', '2003-03-07 17:57:04.000000', NULL, 1),
(231375, 13333, 6110, '<td valign="top">Nice sharp photo, good lighting.</td>', 'Nice sharp photo, good lighting.', '2003-03-07 17:57:52.000000', NULL, 1),
(231376, 13279, 6110, '<td valign="top">I like the lighting &amp; composition.</td>', 'I like the lighting & composition.', '2003-03-07 17:58:32.000000', NULL, 1),
(231377, 13130, 6110, '<td valign="top">Pretty funny.  How''d you do that?</td>', 'Pretty funny.  How''d you do that?', '2003-03-07 18:00:18.000000', NULL, 1),
(231380, 13381, 6110, '<td valign="top">Good macro</td>', 'Good macro', '2003-03-07 18:02:34.000000', NULL, 1),
(231382, 13485, 6110, '<td valign="top">Nice lighting, colorful.  Well done!</td>', 'Nice lighting, colorful.  Well done!', '2003-03-07 18:04:25.000000', NULL, 1),
(231383, 13237, 5728, '<td valign="top">That blue gives this image a very cold feeling, I like it. It seems as this egg is floating in outer space, I like the way you have composed it, the lightness and darkness contrasts are ideal here.</td>', 'That blue gives this image a very cold feeling, I like it. It seems as this egg is floating in outer space, I like the way you have composed it, the lightness and darkness contrasts are ideal here.', '2003-03-07 18:05:58.000000', NULL, 1),
(231385, 13392, 6110, '<td valign="top">The reflections are a bit distracting, maybe use indirect lighting &amp; tripod for longer exposure if necessary?</td>', 'The reflections are a bit distracting, maybe use indirect lighting & tripod for longer exposure if necessary?', '2003-03-07 18:07:59.000000', NULL, 1),
(231386, 13333, 5728, '<td valign="top">Very sharp and very focused! The crop is perfect and the choice to go without a border was good. Only a few reddish spots in the bottom left hand egg holder though, but otherwise an excelent shot.</td>', 'Very sharp and very focused! The crop is perfect and the choice to go without a border was good. Only a few reddish spots in the bottom left hand egg holder though, but otherwise an excelent shot.', '2003-03-07 18:08:25.000000', NULL, 1),
(231388, 13289, 5728, '<td valign="top">This is good! You have the lighting optimal here. The red background fits perfectly.</td>', 'This is good! You have the lighting optimal here. The red background fits perfectly.', '2003-03-07 18:09:44.000000', NULL, 1),
(231389, 13503, 5728, '<td valign="top">You''ve made such a simple shot excellent! The lighting is wonderful, no hot spots to be seen.</td>', 'You''ve made such a simple shot excellent! The lighting is wonderful, no hot spots to be seen.', '2003-03-07 18:10:39.000000', NULL, 1),
(231391, 13282, 5728, '<td valign="top">So simple but so effective. The purple background fits in so well! Good one. Good crop, nice border and the lighting is excellent.</td>', 'So simple but so effective. The purple background fits in so well! Good one. Good crop, nice border and the lighting is excellent.', '2003-03-07 18:11:42.000000', NULL, 1),
(231392, 13306, 5728, '<td valign="top">I like this photo very much. The border seems to be legal as mentioned and the border really does this photo justice. I love the way ou have the photo in black and white and the eggs are blue, very good work!</td>', 'I like this photo very much. The border seems to be legal as mentioned and the border really does this photo justice. I love the way ou have the photo in black and white and the eggs are blue, very good work!', '2003-03-07 18:13:42.000000', NULL, 1),
(231394, 13198, 5728, '<td valign="top">Very good, you have to be proud of this shot! It is so simple but has so much impact! Good lighting.</td>', 'Very good, you have to be proud of this shot! It is so simple but has so much impact! Good lighting.', '2003-03-07 18:15:19.000000', NULL, 1),
(231395, 13447, 5728, '<td valign="top">This is just so funny, it the most humorous photo in the challenge. The cracked eggs are a bonus here. You have given this image so much impact by keeping the eggs sharp and the rest blurred. Excellent!</td>', 'This is just so funny, it the most humorous photo in the challenge. The cracked eggs are a bonus here. You have given this image so much impact by keeping the eggs sharp and the rest blurred. Excellent!', '2003-03-07 18:18:04.000000', NULL, 1),
(231401, 13266, 5728, '<td valign="top">The pastel colours here are wonderful! That gooey transparent part of the egg (which I hate so much!) looks incredible. Cool use of the rule of thirds!</td>', 'The pastel colours here are wonderful! That gooey transparent part of the egg (which I hate so much!) looks incredible. Cool use of the rule of thirds!', '2003-03-07 18:21:32.000000', NULL, 1),
(231404, 13190, 5728, '<td valign="top">You''ve really got the lighting perfect here. This is a photo I would hang on my wall, the textures and colours blend very well.</td>', 'You''ve really got the lighting perfect here. This is a photo I would hang on my wall, the textures and colours blend very well.', '2003-03-07 18:23:00.000000', NULL, 1),
(231406, 13374, 5728, '<td valign="top">This is very quaint! The black background is very fitting and the lighting is excellent, I see no hot spots. The basket seems to be hanging a little in the air, I would have given it a lower crop perhaps.</td>', 'This is very quaint! The black background is very fitting and the lighting is excellent, I see no hot spots. The basket seems to be hanging a little in the air, I would have given it a lower crop perhaps.', '2003-03-07 18:25:16.000000', NULL, 1),
(231414, 13289, 714, '<td valign="top">This is a wonderful picture.  I love the red and crome together.  One thing I would work on is try not to tilt your camera.  The picture is tilted slightly to the left, but not enough to keep me from giving you a 10.</td>', 'This is a wonderful picture.  I love the red and crome together.  One thing I would work on is try not to tilt your camera.  The picture is tilted slightly to the left, but not enough to keep me from giving you a 10.', '2003-03-07 18:56:06.000000', NULL, 1),
(231416, 13276, 714, '<td valign="top">Zachery~I would have to say that this is the best picture you have taken so far.  I am very proud of you for taking your time and trying to understand the camera and its settings.  Keep it up!</td>', 'Zachery~I would have to say that this is the best picture you have taken so far.  I am very proud of you for taking your time and trying to understand the camera and its settings.  Keep it up!', '2003-03-07 18:57:40.000000', NULL, 1),
(231417, 13494, 714, '<td valign="top">I just love this shot.  The lighting, framing, and your choice to have it in b/w.  Perfect picture.  I just wish I thought of it first.  hehehe....vote 10</td>', 'I just love this shot.  The lighting, framing, and your choice to have it in b/w.  Perfect picture.  I just wish I thought of it first.  hehehe....vote 10', '2003-03-07 18:58:55.000000', NULL, 1),
(231419, 13373, 714, '<td valign="top">I really like this picture.  I would have given you a 10, but the egg seems to high in the picture and the bubbles are more of the subject.  I will give you a 9 though.  Good luck.</td>', 'I really like this picture.  I would have given you a 10, but the egg seems to high in the picture and the bubbles are more of the subject.  I will give you a 9 though.  Good luck.', '2003-03-07 19:00:26.000000', NULL, 1),
(231420, 13237, 714, '<td valign="top">Great shot.  It looks like it is floating.  I love the colors and lighting.  Good luck.</td>', 'Great shot.  It looks like it is floating.  I love the colors and lighting.  Good luck.', '2003-03-07 19:01:18.000000', NULL, 1),
(231421, 13306, 714, '<td valign="top">Tara, is this yours?  I am just guessing. I hope you don''t get disqualified.  This is such a cute shot. I think I notice something else that might not be legal.  The painting of the eggs.  We are not supposed to do any touch up painting to the photos.  It is hard to understand all the rules and confusing.  I have been here for a year and have gone through it. so don''t feel bad.</td>', 'Tara, is this yours?  I am just guessing. I hope you don''t get disqualified.  This is such a cute shot. I think I notice something else that might not be legal.  The painting of the eggs.  We are not supposed to do any touch up painting to the photos.  It is hard to understand all the rules and confusing.  I have been here for a year and have gone through it. so don''t feel bad.', '2003-03-07 19:02:06.000000', NULL, 1),
(231445, 13438, 3306, '<td valign="top">If its supposed to be out of focus, I don''t get it.</td>', 'If its supposed to be out of focus, I don''t get it.', '2003-03-07 19:20:34.000000', NULL, 1),
(231447, 13306, 2125, '<td valign="top">definately without question the winner this week 10+  would like to see this with smaller eggs or b and w eggs or smaller and b and w eggs... i would guess that you are a professional portrait photographer and if not you should be .... good luck</td>', 'definately without question the winner this week 10+  would like to see this with smaller eggs or b and w eggs or smaller and b and w eggs... i would guess that you are a professional portrait photographer and if not you should be .... good luck', '2003-03-07 19:25:07.000000', NULL, 1),
(231448, 13413, 2125, '<td valign="top">clever like an egg cocktail!</td>', 'clever like an egg cocktail!', '2003-03-07 19:26:12.000000', NULL, 1),
(231449, 13347, 2125, '<td valign="top">clever set up 8</td>', 'clever set up 8', '2003-03-07 19:27:05.000000', NULL, 1),
(231450, 13495, 2125, '<td valign="top">cute creative!!  must be egg-thrity</td>', 'cute creative!!  must be egg-thrity', '2003-03-07 19:27:53.000000', NULL, 1),
(231451, 13269, 1005, '<td valign="top">Interesting pic.  Did you do the flame part on purpose or is that just the way it worked out?  Colors seem odd/off, focus is probably sharp, but the jpeg artifacts make it hard to tell (color issue could be related).  6 Swash</td>', 'Interesting pic.  Did you do the flame part on purpose or is that just the way it worked out?  Colors seem odd/off, focus is probably sharp, but the jpeg artifacts make it hard to tell (color issue could be related).  6 Swash', '2003-03-07 19:35:08.000000', NULL, 1),
(231452, 13223, 1005, '<td valign="top">Wood fairie of Eggland?  Cute - how did you get the egg to "stand" up?  Focus seems pretty good, color - well not alot to tell,  but I think O.K.  Lighting - also O.K, but the glare could have been softened a little more.  6 Swash</td>', 'Wood fairie of Eggland?  Cute - how did you get the egg to "stand" up?  Focus seems pretty good, color - well not alot to tell,  but I think O.K.  Lighting - also O.K, but the glare could have been softened a little more.  6 Swash', '2003-03-07 19:37:28.000000', NULL, 1),
(231453, 13209, 5418, '<td valign="top">Cool picture, and a great use of the name from one of the best albums ever!</td>', 'Cool picture, and a great use of the name from one of the best albums ever!', '2003-03-07 19:41:56.000000', NULL, 1),
(231454, 13339, 1005, '<td valign="top">Cool idea!  I really like this shot!  I like the purple/lavender color spots on the bubbles (from extra lighting?)  Very nice job!  No complaints at all.  9 Swash</td>', 'Cool idea!  I really like this shot!  I like the purple/lavender color spots on the bubbles (from extra lighting?)  Very nice job!  No complaints at all.  9 Swash', '2003-03-07 19:43:24.000000', NULL, 1),
(231455, 13518, 1005, '<td valign="top">Very nice piece!  The egg shell reminds me of a martian orbit shot or something like that.  I don''t know how it would have worked, but might I suggest a lighting mask to dim the harsh glare below/behind the egg.  Otherwise a very cool shot!  9 Swash</td>', 'Very nice piece!  The egg shell reminds me of a martian orbit shot or something like that.  I don''t know how it would have worked, but might I suggest a lighting mask to dim the harsh glare below/behind the egg.  Otherwise a very cool shot!  9 Swash', '2003-03-07 19:45:23.000000', NULL, 1),
(231457, 13459, 5418, '<td valign="top">One of my outtakes looks exactly like this (except not as sharp as yours)! It''s a great idea nonetheless!</td>', 'One of my outtakes looks exactly like this (except not as sharp as yours)! It''s a great idea nonetheless!', '2003-03-07 19:48:40.000000', NULL, 1),
(231459, 13414, 2158, '<td valign="top">I''d have preferred a photo of the glass egg on its own, and getting in closer.  It looks really beautiful.</td>', 'I''d have preferred a photo of the glass egg on its own, and getting in closer.  It looks really beautiful.', '2003-03-07 19:50:49.000000', NULL, 1),
(231469, 13447, 6870, '<td valign="top">I like the clever  idea here, and the bold approach works well for me. The illustration on the belly looks a little messy and the eggs are a tad out of focus, like the body. I would also try experimenting with more contrasts and different lighting to really get an interesting effect.</td>', 'I like the clever  idea here, and the bold approach works well for me. The illustration on the belly looks a little messy and the eggs are a tad out of focus, like the body. I would also try experimenting with more contrasts and different lighting to really get an interesting effect.', '2003-03-07 20:31:27.000000', NULL, 1),
(231470, 13459, 6870, '<td valign="top">The idea is a good one here, and the placement of the egg is just right. Try a bit sharper focus, or a longer depth of field to get the hold egg in focus. Also, your most interesting light patterns are in the egg white, when I would think you''d want it on the whole of the egg, so try experimenting with light and shadow. I like this.</td>', 'The idea is a good one here, and the placement of the egg is just right. Try a bit sharper focus, or a longer depth of field to get the hold egg in focus. Also, your most interesting light patterns are in the egg white, when I would think you''d want it on the whole of the egg, so try experimenting with light and shadow. I like this.', '2003-03-07 20:33:21.000000', NULL, 1),
(231471, 13339, 6870, '<td valign="top">Really interesting textures, and a nifty, abstract concept.</td>', 'Really interesting textures, and a nifty, abstract concept.', '2003-03-07 20:34:18.000000', NULL, 1),
(231472, 13225, 6870, '<td valign="top">NIce light captured here, and I love the smoke effect (which I recently could not produce to my satisfaction). THe eggs are out of focus, though, and I think this is the key reason the image is not as effective as it could be.</td>', 'NIce light captured here, and I love the smoke effect (which I recently could not produce to my satisfaction). THe eggs are out of focus, though, and I think this is the key reason the image is not as effective as it could be.', '2003-03-07 20:35:32.000000', NULL, 1),
(231473, 13417, 6870, '<td valign="top">Interesting perspective and an intriguing object. In focus too. I like the photo technically, but it doesn''t "do" anything for me. Still, nice work.</td>', 'Interesting perspective and an intriguing object. In focus too. I like the photo technically, but it doesn''t "do" anything for me. Still, nice work.', '2003-03-07 20:36:45.000000', NULL, 1),
(231474, 13316, 6870, '<td valign="top">Well cropped, sharply focused and well composed. It doesn''t "stir" me or "move" me, but it is a well composed shot.</td>', 'Well cropped, sharply focused and well composed. It doesn''t "stir" me or "move" me, but it is a well composed shot.', '2003-03-07 20:37:43.000000', NULL, 1),
(231475, 13129, 6870, '<td valign="top">Lovely colors that invite me to look around. A bit out of focus, when I think that focus is vital.</td>', 'Lovely colors that invite me to look around. A bit out of focus, when I think that focus is vital.', '2003-03-07 20:38:33.000000', NULL, 1),
(231476, 13301, 6870, '<td valign="top">Intriguing perspective, with good lighting and fairly decent focus where it needs to be. The image seems to be calling to me to understand it, with the balanced, wet egg as a clue, but I can''t bring myself to any meaningful conclusion. I suppose it is just an egg on edge.</td>', 'Intriguing perspective, with good lighting and fairly decent focus where it needs to be. The image seems to be calling to me to understand it, with the balanced, wet egg as a clue, but I can''t bring myself to any meaningful conclusion. I suppose it is just an egg on edge.', '2003-03-07 20:40:44.000000', NULL, 1),
(231477, 13450, 6870, '<td valign="top">A clever idea, and fun, too. Try experimenting with angles of light, backdrops and colors to give this photo more impact.</td>', 'A clever idea, and fun, too. Try experimenting with angles of light, backdrops and colors to give this photo more impact.', '2003-03-07 20:41:45.000000', NULL, 1),
(231478, 13411, 6870, '<td valign="top">I like this idea. When I look at this image, my eyes go to where the interesting light is: in the clearish yolk, but I would think that you''d want the interesting light on the whole egg.</td>', 'I like this idea. When I look at this image, my eyes go to where the interesting light is: in the clearish yolk, but I would think that you''d want the interesting light on the whole egg.', '2003-03-07 20:43:05.000000', NULL, 1),
(231480, 13496, 6870, '<td valign="top">I like the idea of an obligatory egg, and I like the placement of the egg in the image. The egg is out of focus, however, when I feel that it should be in focus. Also try experimenting with different light levels and angles to intensify the interest of the shot.</td>', 'I like the idea of an obligatory egg, and I like the placement of the egg in the image. The egg is out of focus, however, when I feel that it should be in focus. Also try experimenting with different light levels and angles to intensify the interest of the shot.', '2003-03-07 20:44:34.000000', NULL, 1),
(231481, 13371, 6870, '<td valign="top">Clever idea and nice placement of the "beheaded" egg in the image. You might try different angles and levels of light to intensify the interest here, and you probably want a sharper focus on the subject.</td>', 'Clever idea and nice placement of the "beheaded" egg in the image. You might try different angles and levels of light to intensify the interest here, and you probably want a sharper focus on the subject.', '2003-03-07 20:46:15.000000', NULL, 1),
(231482, 13320, 6870, '<td valign="top">I don''t get the southern joke, but I do like the still life here. The vibrant colors of the objects might be enhanced with a black background instead of the white. Also try experimenting with different light levels and angles to intensify interest.</td>', 'I don''t get the southern joke, but I do like the still life here. The vibrant colors of the objects might be enhanced with a black background instead of the white. Also try experimenting with different light levels and angles to intensify interest.', '2003-03-07 20:47:51.000000', NULL, 1),
(231483, 13233, 6870, '<td valign="top">Out of focus, but I still like the idea. If you are trying to communicate the precariousness of the egg, a higher perspective with some more interesting light levels and angles may be in order, too.</td>', 'Out of focus, but I still like the idea. If you are trying to communicate the precariousness of the egg, a higher perspective with some more interesting light levels and angles may be in order, too.', '2003-03-07 20:49:15.000000', NULL, 1),
(231498, 13391, 6477, '<td valign="top">LOL very funny:)</td>', 'LOL very funny:)', '2003-03-07 21:18:25.000000', NULL, 1),
(231503, 13363, 6325, '<td valign="top">I like the strong, but muted colors. Nice lighting and composition. I would love to see this printed on water color  or some other tectured paper.</td>', 'I like the strong, but muted colors. Nice lighting and composition. I would love to see this printed on water color  or some other tectured paper.', '2003-03-07 21:31:29.000000', NULL, 1),
(231515, 13471, 1280, '<td valign="top">The idea is cute, but the quality has suffered.  It''s very blurry.  It may have happened in processing.</td>', 'The idea is cute, but the quality has suffered.  It''s very blurry.  It may have happened in processing.', '2003-03-07 22:18:24.000000', NULL, 1),
(231516, 13219, 2677, '<td valign="top">Nice lighting effect!  I love it.</td>', 'Nice lighting effect!  I love it.', '2003-03-07 22:18:34.000000', NULL, 1),
(231518, 13224, 1280, '<td valign="top">Very good detail.</td>', 'Very good detail.', '2003-03-07 22:19:26.000000', NULL, 1),
(231519, 13409, 7175, '<td valign="top">I voted this a poor score because the egg is not even visible here..</td>', 'I voted this a poor score because the egg is not even visible here..', '2003-03-07 22:22:36.000000', NULL, 1),
(231520, 13476, 7175, '<td valign="top">Interesting composure and color balance</td>', 'Interesting composure and color balance', '2003-03-07 22:22:59.000000', NULL, 1),
(231521, 13290, 7175, '<td valign="top">Very interesting.. high score. Love the lines, with the shape of the egg. Well done.</td>', 'Very interesting.. high score. Love the lines, with the shape of the egg. Well done.', '2003-03-07 22:24:29.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(231522, 13249, 7175, '<td valign="top">Very brilliant colors. Well done!</td>', 'Very brilliant colors. Well done!', '2003-03-07 22:25:36.000000', NULL, 1),
(231523, 13448, 7175, '<td valign="top">Flash too bright in areas, and edges darkend, could have done more with the egg.</td>', 'Flash too bright in areas, and edges darkend, could have done more with the egg.', '2003-03-07 22:26:41.000000', NULL, 1),
