(231757, 13249, 7033, '<td valign="top">Outstanding!  I especially love the deeply saturated colors and the contrast between the yellow and blue.</td>', 'Outstanding!  I especially love the deeply saturated colors and the contrast between the yellow and blue.', '2003-03-08 16:42:07.000000', NULL, 1),
(231758, 13364, 7033, '<td valign="top">Striking photo!  I especially love the lighting.  After looking a second or two longer, the reflections come into play, and the line between the eggs and their reflection takes over.  Nicely done.</td>', 'Striking photo!  I especially love the lighting.  After looking a second or two longer, the reflections come into play, and the line between the eggs and their reflection takes over.  Nicely done.', '2003-03-08 16:44:10.000000', NULL, 1),
