(231762, 13401, 7033, '<td valign="top">Nice shot of an ordinary subject.  The deeply saturated yellow really adds to the picture overall.</td>', 'Nice shot of an ordinary subject.  The deeply saturated yellow really adds to the picture overall.', '2003-03-08 16:50:18.000000', NULL, 1),
