(231859, 13321, 6479, '<td valign="top">Good job. Nice pic.</td>', 'Good job. Nice pic.', '2003-03-08 22:00:55.000000', NULL, 1),
(231860, 13235, 6479, '<td valign="top">Good job. Nice pic.</td>', 'Good job. Nice pic.', '2003-03-08 22:01:10.000000', NULL, 1),
(231861, 13353, 6870, '<td valign="top">NIftycolors,and the lined background accentuates the roundness of the eggs. I can''t see a reason for it to be out of focus, though.</td>', 'NIftycolors,and the lined background accentuates the roundness of the eggs. I can''t see a reason for it to be out of focus, though.', '2003-03-08 22:02:13.000000', NULL, 1),
(231862, 13178, 1280, '<td valign="top">I like it!</td>', 'I like it!', '2003-03-08 22:02:56.000000', NULL, 1),
(231863, 13498, 6479, '<td valign="top">Good job. Nice pic.</td>', 'Good job. Nice pic.', '2003-03-08 22:03:39.000000', NULL, 1),
(231864, 13400, 6479, '<td valign="top">Good job. Nice pic.</td>', 'Good job. Nice pic.', '2003-03-08 22:03:50.000000', NULL, 1),
(231865, 13333, 6870, '<td valign="top">Fun idea, and the crate is captured wonderfully. For some reason, the eggs don''t seem to be as in focus as the crate. Perhaps the lighting could be shifted to make them more clear, or try a faster exposure to make them just a tad darker?</td>', 'Fun idea, and the crate is captured wonderfully. For some reason, the eggs don''t seem to be as in focus as the crate. Perhaps the lighting could be shifted to make them more clear, or try a faster exposure to make them just a tad darker?', '2003-03-08 22:03:51.000000', NULL, 1),
(231866, 13378, 6479, '<td valign="top">Good job. Nice pic.</td>', 'Good job. Nice pic.', '2003-03-08 22:04:02.000000', NULL, 1),
