(231870, 13488, 6479, '<td valign="top">Good job. Nice pic.</td>', 'Good job. Nice pic.', '2003-03-08 22:04:44.000000', NULL, 1),
(231871, 13243, 6870, '<td valign="top">Clever idea, and engaging image. I wish they were in focus.</td>', 'Clever idea, and engaging image. I wish they were in focus.', '2003-03-08 22:04:47.000000', NULL, 1),
