(231878, 13482, 6479, '<td valign="top">Good job. Nice pic.</td>', 'Good job. Nice pic.', '2003-03-08 22:06:15.000000', NULL, 1),
(231879, 13184, 6870, '<td valign="top">Lovely eggs. Colors are captured well, and they are in focus. Try experimenting with dif. levels and angles of light to reallyreveal the drama here.</td>', 'Lovely eggs. Colors are captured well, and they are in focus. Try experimenting with dif. levels and angles of light to reallyreveal the drama here.', '2003-03-08 22:06:18.000000', NULL, 1),
