INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3761412, 13319, 66635, '<td valign="top">Cool pic.  I used to do this as a kid.  We called them "rubber eggs" because the bounce a little.</td>', 'Cool pic.  I used to do this as a kid.  We called them "rubber eggs" because the bounce a little.', '2007-06-09 21:49:38.000000', NULL, 0),
(4070285, 13194, 67579, '<td valign="top">Wow beautiful photo, love the warm lighting and semingly perfect reflection, and the rose although at first to me seemed out of place works realy well :)<br/> <br/>-dave</td>', 'Wow beautiful photo, love the warm lighting and semingly perfect reflection, and the rose although at first to me seemed out of place works realy well :) -dave', '2007-09-07 20:00:17.000000', NULL, 0),
(4230199, 13249, 43463, '<td valign="top">I like the color tones and composition of this piece. The half circle of the bold yellow yolk is the center with the grooves in the plate invoke the idea of concentric circles rippling out from the center. I do wish the  yellow yolk was a tad more up so that it would further strengthen the connection that it is the center from which those groves are radiating/rippling out from. Still it is a very interesting composition at times invoking a conceptual idea (I don''t know if that was your intention when you created the piece) The composition invokes the idea that the yolk is the sun and the grooves of the plate are the planetary revolutions around it.</td>', 'I like the color tones and composition of this piece. The half circle of the bold yellow yolk is the center with the grooves in the plate invoke the idea of concentric circles rippling out from the center. I do wish the  yellow yolk was a tad more up so that it would further strengthen the connection that it is the center from which those groves are radiating/rippling out from. Still it is a very interesting composition at times invoking a conceptual idea (I don''t know if that was your intention when you created the piece) The composition invokes the idea that the yolk is the sun and the grooves of the plate are the planetary revolutions around it.', '2007-11-07 22:03:59.000000', NULL, 0),
(4394284, 13382, 78132, '<td valign="top">Awesome shot!!!</td>', 'Awesome shot!!!', '2008-01-15 17:09:56.000000', NULL, 0),
